INSERT INTO work_queue(id,task_type,payload,status,created_at)
SELECT 'summer-days-wav-guard','metadata','{}','guard_failed',unixepoch()
WHERE NOT ((SELECT COUNT(*) FROM c JOIN song_masters sm ON sm.id=c.master_id AND sm.album_id='pending-uploads' AND sm.title=c.title AND sm.track IS NULL AND sm.disc IS NULL JOIN song_instances si ON si.id=c.instance_id AND si.master_id=sm.id AND si.source_id='r2-local' AND si.source_type='original' AND si.missing=0 AND si.tag_scanned=1 AND lower(si.suffix)='wav' AND si.storage_object_id=c.object_id JOIN storage_objects so ON so.id=c.object_id AND so.physical_key=c.physical_key JOIN storage_entries se ON se.id=c.entry_id AND se.instance_id=si.id AND se.object_id=c.object_id AND se.parent_id=c.parent_id AND se.path=c.path AND se.kind='file')=8 AND (SELECT COUNT(*) FROM storage_entries WHERE parent_id='se-490ce26c57434b328ad9f3e67cfb4ef3' AND kind='file')=8 AND NOT EXISTS(SELECT 1 FROM albums WHERE id='al-summer-days-wav') AND (SELECT COUNT(*) FROM albums WHERE id='al-2b21b237dc' AND name='Summer Days' AND song_count=7)=1 AND NOT EXISTS(SELECT 1 FROM album_display_group_members WHERE album_id='al-2b21b237dc'));
INSERT INTO albums(id,name,sort_name,year,song_count,duration,size,created_at,updated_at) VALUES('al-summer-days-wav','Summer Days','summer days',2012,0,0,0,unixepoch(),unixepoch());
WITH c(master_id,track_no) AS (VALUES ('sm-upload-2108ede5-c31',1),('sm-upload-e2b18d47-ca7',2),('sm-upload-05875896-e06',3),('sm-upload-ad152a69-a46',4),('sm-upload-dd26cda1-cef',5),('sm-upload-521326c5-da0',6),('sm-upload-f039ff21-f82',7),('sm-upload-7033e52e-a49',8)) UPDATE song_masters SET album_id='al-summer-days-wav',disc=1,track=(SELECT track_no FROM c WHERE c.master_id=song_masters.id),updated_at=unixepoch() WHERE id IN(SELECT master_id FROM c) AND album_id='pending-uploads' AND track IS NULL AND disc IS NULL;
INSERT INTO work_queue(id,task_type,payload,status,created_at) SELECT 'summer-days-wav-guard','metadata','{}','guard_failed',unixepoch() WHERE changes()!=8;
UPDATE albums SET song_count=(SELECT COUNT(*) FROM song_masters WHERE album_id=albums.id),duration=(SELECT COALESCE(SUM(duration),0) FROM song_masters WHERE album_id=albums.id),size=(SELECT COALESCE(SUM(si.size),0) FROM song_masters sm JOIN song_instances si ON si.master_id=sm.id WHERE sm.album_id=albums.id),updated_at=unixepoch() WHERE id IN('pending-uploads','al-summer-days-wav');
